import {profileContour} from './profile-contour.js';
import {detectedPoints,fitParameters,manualGuides,labels,pointKeys} from './photo-fit.js';
import {definitions} from './model.js';
const names=Object.fromEntries(definitions.flatMap(([,ds])=>ds.map(([k,name])=>[k,name])));
export function initPhotoFit({getState,applyState}){
const $=s=>document.querySelector(s),dialog=$('#photo-dialog'),canvas=$('#photo-canvas'),ctx=canvas.getContext('2d'),status=$('#photo-status');
let image=null,points=null,worker=null,timeout=null,job=0,selection=0,manual=false,fit=null,report=null,undo=null,reference=null,referencePromise=null,skipLips=false,confirmed=false,dragging=false;
const mode=()=>$('#photo-mode').value;
const say=t=>{status.textContent=t;};
function cancel(){job++;clearTimeout(timeout);worker?.terminate();worker=null;$('#photo-detect').disabled=!image;}
function invalidate(){fit=null;$('#photo-apply').disabled=true;$('#photo-results').replaceChildren();}
function clearPoints(){points=null;report=null;manual=false;confirmed=false;skipLips=false;$('#photo-confirm').checked=false;$('#photo-skip-lips').checked=false;invalidate();$('#photo-point-tools').hidden=true;}
function close(){cancel();dragging=false;image=null;points=null;fit=null;canvas.width=1;canvas.height=1;$('#photo-image-area').hidden=true;$('#photo-point-tools').hidden=true;$('#photo-results').replaceChildren();$('#photo-empty').hidden=false;$('#photo-file').value='';$('#photo-manual').disabled=true;$('#photo-rotate').disabled=true;$('#photo-apply').disabled=true;$('#photo-detect').disabled=true;say('選択した向きから、顔または体がはっきり写った画像を選んでください。');}
$('#photo-open').onclick=()=>{dialog.showModal();$('#photo-undo').disabled=!undo;};$('#photo-close').onclick=()=>dialog.close();dialog.addEventListener('close',close);$('#photo-mode').onchange=()=>{cancel();clearPoints();$('#photo-height-row').hidden=!mode().startsWith('body');$('#photo-expression-row').hidden=mode()!=='face';paint();if(image)say('モードを変更しました。自動検出するか、手動で点を指定してください。');};
async function base(){if(reference)return reference;if(!referencePromise)referencePromise=fetch('./base-model.json').then(r=>{if(!r.ok)throw Error('基準モデルを読み込めませんでした。');return r.json();}).then(d=>reference=d).catch(e=>{referencePromise=null;throw e;});return referencePromise;}
$('#photo-choose').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#photo-file').click();}};
$('#photo-file').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;cancel();clearPoints();const id=job;say('画像を読み込み中…');try{if(file.size>25*1024*1024)throw Error('25MB以下の画像を選んでください。');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('画像を開けません。JPEG・PNG・WebP形式で保存して選んでください。'));img.src=url;});if(id!==job)return;if(img.naturalWidth<100||img.naturalHeight<100)throw Error('100×100ピクセル以上の画像を選んでください。');const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),surface=document.createElement('canvas');surface.width=Math.round(img.naturalWidth*scale);surface.height=Math.round(img.naturalHeight*scale);surface.getContext('2d').drawImage(img,0,0,surface.width,surface.height);image=surface;}finally{URL.revokeObjectURL(url);}if(id!==job)return;$('#photo-empty').hidden=true;$('#photo-image-area').hidden=false;for(const s of ['#photo-detect','#photo-manual','#photo-rotate'])$(s).disabled=false;paint();detect();}catch(err){if(id===job){image=null;$('#photo-image-area').hidden=true;$('#photo-empty').hidden=false;say(err.message);}}};
$('#photo-rotate').onclick=()=>{if(!image)return;cancel();clearPoints();const s=document.createElement('canvas');s.width=image.height;s.height=image.width;const c=s.getContext('2d');c.translate(s.width,0);c.rotate(Math.PI/2);c.drawImage(image,0,0);image=s;paint();say('画像を回転しました。自動検出をやり直してください。');};
function tryProfile(){if(!image||!mode().startsWith('face'))return false;try{const scaled=document.createElement('canvas'),factor=Math.min(1,512/Math.max(image.width,image.height));scaled.width=Math.round(image.width*factor);scaled.height=Math.round(image.height*factor);const c=scaled.getContext('2d',{willReadFrequently:true});c.drawImage(image,0,0,scaled.width,scaled.height);const candidate=profileContour(c.getImageData(0,0,scaled.width,scaled.height).data,scaled.width,scaled.height);$('#photo-mode').value='faceSide';$('#photo-height-row').hidden=true;$('#photo-expression-row').hidden=true;points=Object.fromEntries(Object.entries(candidate.points).map(([k,p])=>[k,{x:p.x*image.width/scaled.width,y:p.y*image.height/scaled.height}]));report=candidate;manual=true;confirmed=false;skipLips=true;setupPoints();paint();say(candidate.warnings.join('\n')+'\n6点を確認し、位置確認にチェックすると計算できます。');return true;}catch{return false;}}

async function detect(){if(!image)return;cancel();clearPoints();const id=job;
if(mode()==='faceSide'&&tryProfile())return;
$('#photo-detect').disabled=true;say('自動検出を開始します…');paint();try{if(typeof OffscreenCanvas==='undefined'||typeof createImageBitmap==='undefined')throw Error('このブラウザでは自動検出を利用できません。手動で点を指定できます。');const bitmap=await createImageBitmap(image);if(id!==job){bitmap.close();return;}worker=new Worker(new URL('./photo-worker.js',import.meta.url));worker.onmessage=({data})=>{if(id!==job)return;if(data.stage){say(data.stage);return;}clearTimeout(timeout);worker?.terminate();worker=null;$('#photo-detect').disabled=false;if(data.error){if(!tryProfile())say(data.error);return;}try{report=detectedPoints(data.result,mode(),image.width,image.height);points=report.points;skipLips=report.skipLips;$('#photo-skip-lips').checked=skipLips;manual=false;confirmed=true;setupPoints();paint();calculate();}catch(e){if(!tryProfile())say(e.message);}};worker.onerror=()=>{if(id===job){cancel();if(!tryProfile())say('自動検出を開始できませんでした。手動で点を指定できます。');}};worker.postMessage({bitmap,mode:mode()},[bitmap]);timeout=setTimeout(()=>{if(id===job){cancel();if(!tryProfile())say('読み込みがタイムアウトしました。再試行するか、手動で点を指定してください。');}},90000);}catch(e){if(id===job){$('#photo-detect').disabled=false;if(!tryProfile())say(e.message);}}}
$('#photo-detect').onclick=detect;
$('#photo-manual').onclick=()=>{if(!image)return;cancel();clearPoints();points=manualGuides(mode(),image.width,image.height);manual=true;confirmed=false;setupPoints();paint();say('点はガイド位置です（未検出）。写真に合わせて点を動かし、位置確認にチェックしてください。');};
function setupPoints(){selection=0;$('#photo-point-tools').hidden=false;$('#photo-confirm-row').hidden=!manual;const select=$('#photo-point');select.replaceChildren();pointKeys[mode()].forEach((k,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+'. '+labels[k];select.append(o);});}
function paint(){if(!image)return;canvas.width=image.width;canvas.height=image.height;ctx.drawImage(image,0,0);if(!points)return;const scale=canvas.width/Math.max(1,canvas.clientWidth||canvas.width),r=6*scale;const connections=mode()==='faceSide'?[['forehead','chin'],['noseRoot','noseTip'],['noseTip','noseBase'],['noseBase','mouth'],['mouth','chin']]:mode()==='bodySide'?[['shoulder','hip'],['chestA','chestB'],['waistA','waistB'],['pelvisA','pelvisB']]:mode()==='face'?[['forehead','chin'],['cheekL','cheekR'],['jawL','jawR'],['eyeL','eyeR'],['lipTop','lipBottom'],['mouthL','mouthR']]:[['shoulderL','shoulderR'],['hipL','hipR'],['hipL','kneeL'],['kneeL','ankleL'],['hipR','kneeR'],['kneeR','ankleR'],['waistL','waistR'],['pelvisL','pelvisR']];ctx.lineWidth=1.5*scale;ctx.strokeStyle='#bbe9d0';ctx.setLineDash([4*scale,4*scale]);for(const[a,b]of connections){ctx.beginPath();ctx.moveTo(points[a].x,points[a].y);ctx.lineTo(points[b].x,points[b].y);ctx.stroke();}ctx.setLineDash([]);pointKeys[mode()].forEach((k,i)=>{const p=points[k];ctx.beginPath();ctx.arc(p.x,p.y,r*(i===selection?1.4:1),0,Math.PI*2);ctx.fillStyle=i===selection?'#ffe49e':'#bbddc8';ctx.fill();ctx.strokeStyle='#10221e';ctx.lineWidth=1.5*scale;ctx.stroke();ctx.font=`bold ${12*scale}px sans-serif`;ctx.textAlign='center';ctx.lineWidth=3*scale;ctx.strokeStyle='#10221e';ctx.strokeText(String(i+1),p.x,p.y-r-4*scale);ctx.fillStyle='#fff';ctx.fillText(String(i+1),p.x,p.y-r-4*scale);});}
new ResizeObserver(()=>{if(dialog.open)paint();}).observe($('#photo-image-area'));
$('#photo-point').onchange=e=>{selection=Number(e.target.value);paint();};
function edit(x,y){if(!points||!image)return;const key=pointKeys[mode()][selection];points[key]={x:Math.max(0,Math.min(image.width-1,x)),y:Math.max(0,Math.min(image.height-1,y))};invalidate();if(manual){confirmed=false;$('#photo-confirm').checked=false;}paint();}
const pos=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
canvas.onpointerdown=e=>{if(!points||dragging!==false)return;e.preventDefault();const p=pos(e),radius=24*canvas.width/canvas.clientWidth;let nearest=radius;pointKeys[mode()].forEach((k,i)=>{const d=Math.hypot(points[k].x-p.x,points[k].y-p.y);if(d<nearest){nearest=d;selection=i;}});$('#photo-point').value=String(selection);canvas.setPointerCapture(e.pointerId);dragging=e.pointerId;edit(p.x,p.y);};canvas.onpointermove=e=>{if(dragging!==e.pointerId)return;const p=pos(e);edit(p.x,p.y);};for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,e=>{if(dragging!==e.pointerId)return;dragging=false;if(!manual)calculate();});
canvas.onkeydown=e=>{const directions={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},d=directions[e.key];if(!d||!points)return;e.preventDefault();const p=points[pointKeys[mode()][selection]],s=e.shiftKey?5:1;edit(p.x+d[0]*s,p.y+d[1]*s);if(!manual)calculate();};
$('#photo-confirm').onchange=e=>{confirmed=e.target.checked;if(confirmed)calculate();else invalidate();};$('#photo-skip-lips').onchange=e=>{skipLips=e.target.checked;calculate();};$('#photo-calculate').onclick=calculate;$('#photo-height').oninput=invalidate;
async function calculate(){invalidate();if(!points)return;if(manual&&!confirmed){say('すべての点を写真に合わせてから、位置確認にチェックしてください。');return;}const id=job,snapshot=JSON.stringify(points),selectedMode=mode();say('画像の比率に合うパラメータを計算中…');try{const d=await base();if(id!==job||snapshot!==JSON.stringify(points)||selectedMode!==mode())return;const r=fitParameters(d,points,selectedMode,getState().params,{skipLips});if(selectedMode.startsWith('body')&&$('#photo-height').value!==''){const h=Number($('#photo-height').value);if(!Number.isFinite(h)||h<145||h>205)throw Error('身長は145〜205cmの範囲で入力してください。空欄なら現在の身長を維持します。');r.params.height=h/100;r.keys.push('height');}fit=r;const current=getState().params,table=document.createElement('table');const head=document.createElement('thead');head.innerHTML='<tr><th>項目</th><th>現在</th><th>推定</th></tr>';table.append(head);const tbody=document.createElement('tbody');for(const k of r.keys){const row=document.createElement('tr');for(const v of [names[k],k==='height'?Math.round(current[k]*100)+' cm':current[k].toFixed(2),k==='height'?Math.round(r.params[k]*100)+' cm':r.params[k].toFixed(2)]){const td=document.createElement('td');td.textContent=v;row.append(td);}tbody.append(row);}table.append(tbody);$('#photo-results').replaceChildren(table);$('#photo-apply').disabled=false;const notes=[manual?(report?.method==='profile-contour'?'輪郭検出の候補点を確認して計算しました。':'手動の特徴点から計算しました。'):'自動検出しました。点を動かして修正できます。',...(report?.warnings||[]),`モデルと画像の比率の平均ずれ: ${(r.relativeError*100).toFixed(1)}%（検出の確信度ではありません）`];if(r.hitLimits.length)notes.push('調整範囲の端: '+r.hitLimits.map(k=>names[k]).join('・'));if(r.relativeError>.15)notes.push('差が大きいため、特徴点や撮影角度を確認してください。');say(notes.join('\n'));}catch(e){say(e.message);}}
$('#photo-apply').onclick=()=>{if(!fit)return;const before=getState(),next={...before.params};for(const k of fit.keys)next[k]=fit.params[k];undo=structuredClone(before);applyState({params:next,source:'data',mode:mode().startsWith('face')?'face':'body',side:mode().endsWith('Side')});dialog.close();$('#photo-open').textContent='画像からモデルを作る · 反映済み';};
$('#photo-undo').onclick=()=>{if(!undo)return;applyState(undo);undo=null;$('#photo-undo').disabled=true;invalidate();$('#photo-open').textContent='画像からモデルを作る';say('直前の画像反映を取り消しました。');};
}
